static String readWithFallback(Path file) throws IOException {
    byte[] bajty = Files.readAllBytes(file);
    CharsetDecoder decoder = StandardCharsets.UTF_8.newDecoder()
            .onMalformedInput(CodingErrorAction.REPORT)
            .onUnmappableCharacter(CodingErrorAction.REPORT);
    try {
        return decoder.decode(ByteBuffer.wrap(bajty)).toString();
    } catch (CharacterCodingException e) {
        return new String(bajty, StandardCharsets.ISO_8859_1);
    }
}

static Charset detectCharset(Path file, Charset... candidates) throws IOException {
    byte[] bajty = Files.readAllBytes(file);
    for (Charset cs : candidates) {
        CharsetDecoder decoder = cs.newDecoder()
                .onMalformedInput(CodingErrorAction.REPORT)
                .onUnmappableCharacter(CodingErrorAction.REPORT);
        try {
            decoder.decode(ByteBuffer.wrap(bajty));
            return cs;
        } catch (CharacterCodingException ignored) { }
    }
    return null;
}

static void convertFileCharset(Path in, Charset from, Path out, Charset to) throws IOException {
    String tresc = Files.readString(in, from);
    Files.writeString(out, tresc, to);
}

static boolean isValidUtf8(byte[] data) {
    int i = 0;
    while (i < data.length) {
        int b = data[i] & 0xFF;
        int extraBytes;
        if ((b & 0x80) == 0) extraBytes = 0;
        else if ((b & 0xE0) == 0xC0) extraBytes = 1;
        else if ((b & 0xF0) == 0xE0) extraBytes = 2;
        else if ((b & 0xF8) == 0xF0) extraBytes = 3;
        else return false;
        for (int j = 1; j <= extraBytes; j++) {
            if (i + j >= data.length || (data[i + j] & 0xC0) != 0x80) return false;
        }
        i += extraBytes + 1;
    }
    return true;
}

