static void scanDirectory(Path dir) throws IOException {
    try (Stream<Path> lista = Files.list(dir)) {
        for (Path p : (Iterable<Path>) lista::iterator) {
            byte[] dane = Files.readAllBytes(p);
            CharsetDecoder decoder = StandardCharsets.UTF_8.newDecoder()
                    .onMalformedInput(CodingErrorAction.REPORT)
                    .onUnmappableCharacter(CodingErrorAction.REPORT);
            try {
                decoder.decode(ByteBuffer.wrap(dane));
                System.out.println(p.getFileName() + ": OK");
            } catch (CharacterCodingException e) {
                System.out.println(p.getFileName() + ": NIEPOPRAWNY UTF-8");
            }
        }
    }
}

static void transcode(Path in, Charset from, Path out, Charset to) throws IOException {
    try (var reader = new InputStreamReader(Files.newInputStream(in), from);
         var writer = new OutputStreamWriter(Files.newOutputStream(out), to)) {
        char[] buf = new char[1024];
        int n;
        while ((n = reader.read(buf)) != -1) {
            writer.write(buf, 0, n);
        }
    }
}

