static Charset guessCharset(byte[] data) {
    if (data.length >= 2) {
        int b0 = data[0] & 0xFF, b1 = data[1] & 0xFF;
        if ((b0 == 0xFE && b1 == 0xFF) || (b0 == 0xFF && b1 == 0xFE)) {
            return StandardCharsets.UTF_16;
        }
    }
    if (isValidUtf8(data)) {
        return StandardCharsets.UTF_8;
    }
    return StandardCharsets.ISO_8859_1;
}

static void mergeLogs(Map<Path, Charset> filesWithEncodings, Path output) throws IOException {
    List<String> wszystkieLinie = new ArrayList<>();
    for (Map.Entry<Path, Charset> entry : filesWithEncodings.entrySet()) {
        wszystkieLinie.addAll(Files.readAllLines(entry.getKey(), entry.getValue()));
    }
    Files.write(output, wszystkieLinie, StandardCharsets.UTF_8);
}
